#!/usr/bin/env python3
"""Offline relationship inference with exact bounded-width sum-product."""
import json
import math
import re
import sys


class Invalid(Exception):
    pass


def require(ok):
    if not ok:
        raise Invalid()


def integer(value, low, high):
    return type(value) is int and low <= value <= high


def asn(value):
    return integer(value, 1, 4294967295)


def fields(value, names):
    require(type(value) is dict and value.keys() == names)


def array(value, maximum):
    require(type(value) is list and len(value) <= maximum)


def path_field(value):
    array(value, 64)
    require(all(asn(x) for x in value))


def link_field(value):
    require(type(value) is list and len(value) == 2)
    require(all(asn(x) for x in value) and value[0] != value[1])
    return canonical(*value)


def canonical(a, b):
    return (a, b) if a < b else (b, a)


def unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise Invalid()
        result[key] = value
    return result


def bad_number(_):
    raise Invalid()


def parse_integer(text):
    # Every schema field has an absolute bound of at most 4294967295.
    if len(text) > 11:
        raise Invalid()
    return int(text)


def validate(data):
    fields(data, {'version', 'ixps', 'rib', 'priors', 'declared', 'order', 'queries'})
    require(integer(data['version'], 1, 1))
    array(data['ixps'], 1024)
    require(all(asn(x) for x in data['ixps']))
    require(len(set(data['ixps'])) == len(data['ixps']))
    array(data['rib'], 2000)
    total_length = 0
    for record in data['rib']:
        fields(record, {'path', 'count'})
        path_field(record['path'])
        total_length += len(record['path'])
        require(integer(record['count'], 1, 1000000))
    require(total_length <= 40000)
    array(data['priors'], 2000)
    seen = set()
    for record in data['priors']:
        fields(record, {'link', 'weights'})
        edge = link_field(record['link'])
        require(edge not in seen)
        seen.add(edge)
        w = record['weights']
        require(type(w) is list and len(w) == 3)
        require(all(integer(x, 0, 1000000) for x in w) and sum(w) > 0)
    array(data['declared'], 2000)
    seen = set()
    for record in data['declared']:
        fields(record, {'link', 'rel'})
        edge = link_field(record['link'])
        require(edge not in seen)
        seen.add(edge)
        require(type(record['rel']) is str and record['rel'] in ('c2p', 'p2p', 'p2c'))
    array(data['order'], 64)
    seen = set()
    for link in data['order']:
        edge = link_field(link)
        require(link[0] < link[1] and edge not in seen)
        seen.add(edge)
    array(data['queries'], 512)
    seen = set()
    for record in data['queries']:
        fields(record, {'id', 'path', 'threshold'})
        name = record['id']
        require(type(name) is str and re.fullmatch(r'[A-Za-z0-9_.-]{1,64}', name) is not None)
        require(name not in seen)
        seen.add(name)
        path_field(record['path'])
        t = record['threshold']
        require(type(t) is list and len(t) == 2)
        require(integer(t[1], 1, 1000000) and integer(t[0], 0, t[1]))


def clean(path, ixps):
    result = []
    for x in path:
        if x not in ixps and (not result or x != result[-1]):
            result.append(x)
    return tuple(result)


def topology(data, ixps):
    paths = {}
    for record in data['rib']:
        path = clean(record['path'], ixps)
        if len(path) >= 2 and len(set(path)) == len(path):
            paths[path] = paths.get(path, 0) + record['count']
    rounds = {}
    for path in paths:
        for a, b in zip(path, path[1:]):
            rounds[canonical(a, b)] = 0
    require(len(rounds) <= 4096)
    r = 1
    while paths:
        # A bit for each canonical endpoint survives only if that *same*
        # endpoint is external in every current path containing the link.
        masks = {}
        for path in paths:
            first, last = path[0], path[-1]
            for a, b in zip(path, path[1:]):
                edge = canonical(a, b)
                u, v = edge
                mask = int(u == first or u == last) | (int(v == first or v == last) << 1)
                masks[edge] = masks.get(edge, 3) & mask
        removed = {edge for edge, mask in masks.items() if mask}
        if not removed:
            break
        for edge in removed:
            rounds[edge] = r
        trimmed = {}
        for path, count in paths.items():
            start = int(canonical(path[0], path[1]) in removed)
            end = len(path) - int(canonical(path[-2], path[-1]) in removed)
            if end - start >= 2:
                p = path[start:end]
                trimmed[p] = trimmed.get(p, 0) + count
        paths = trimmed
        r += 1
    return paths, rounds


def core_structure(paths, rounds, order):
    core = {edge for edge, r in rounds.items() if r == 0}
    ordered = [tuple(edge) for edge in order]
    require(set(ordered) == core)
    n = len(ordered)
    index = {edge: i for i, edge in enumerate(ordered)}
    contexts = [{} for _ in range(n)]
    for path, count in paths.items():
        # A code 2*i + reverse denotes a directed view of variable i.
        codes = [2 * index[canonical(a, b)] + int(a > b)
                 for a, b in zip(path, path[1:])]
        for j, code in enumerate(codes):
            if code & 1:
                left = (codes[j + 1] ^ 1) if j + 1 < len(codes) else -1
                right = (codes[j - 1] ^ 1) if j > 0 else -1
            else:
                left = codes[j - 1] if j > 0 else -1
                right = codes[j + 1] if j + 1 < len(codes) else -1
            ctx = (left, right)
            bucket = contexts[code // 2]
            bucket[ctx] = bucket.get(ctx, 0) + count
    scopes = []
    graph = [set() for _ in range(n)]
    for i, context in enumerate(contexts):
        scope = {i}
        for left, right in context:
            if left >= 0:
                scope.add(left // 2)
            if right >= 0:
                scope.add(right // 2)
        scopes.append(tuple(sorted(scope)))
        for v in scope:
            graph[v].update(scope - {v})
    bags = []
    parents = []
    for i in range(n):
        neighbors = sorted(graph[i])
        require(len(neighbors) <= 4)
        bags.append((i, *neighbors))
        parents.append(neighbors[0] if neighbors else -1)
        for v in neighbors:
            graph[v].remove(i)
            graph[v].update(x for x in neighbors if x != v)
        graph[i].clear()
    return ordered, contexts, scopes, bags, parents


POW3 = (1, 3, 9, 27, 81, 243)
G = ((0, 0, 1), (1, 1, 2), (1, 1, 2))


def projection(big, small):
    """Flat base-three table indices for marginal/restriction to small."""
    positions = [(POW3[big.index(v)], POW3[j]) for j, v in enumerate(small)]
    return [sum(((s // p) % 3) * q for p, q in positions)
            for s in range(POW3[len(big)] )]


def reduced_vector(nums, denominator):
    common = denominator
    for x in nums:
        common = math.gcd(common, x)
    return tuple(x // common for x in nums) + (denominator // common,)


def infer(ordered, contexts, scopes, bags, parents):
    """Integer clique-tree messages. No approximations or positive-weight guesses.

    The elimination tree's bag has the eliminated variable first. Its outgoing
    separator is the rest of that bag. Original potentials go into the first
    bucket in their scope; fill edges guarantee the separator is in its parent.
    """
    n = len(ordered)
    local = [[1] * POW3[len(bag)] for bag in bags]
    for center in range(n):
        scope = scopes[center]
        positions = {v: j for j, v in enumerate(scope)}
        center_pos = positions[center]
        terms = []
        for (left, right), count in contexts[center].items():
            lp = positions[left // 2] if left >= 0 else -1
            rp = positions[right // 2] if right >= 0 else -1
            terms.append((lp, left & 1, rp, right & 1, count))
        factor = []
        for assignment in range(POW3[len(scope)]):
            states = [(assignment // POW3[j]) % 3 for j in range(len(scope))]
            t = states[center_pos]
            value = 0
            for lp, lr, rp, rr, count in terms:
                l = states[lp] if lp >= 0 else 0
                r = states[rp] if rp >= 0 else 2
                if lp >= 0 and lr:
                    l = 2 - l
                if rp >= 0 and rr:
                    r = 2 - r
                if t == G[l][r]:
                    value += count
            factor.append(value)
        owner = scope[0]
        mapping = projection(bags[owner], scope)
        table = local[owner]
        for j, f in enumerate(mapping):
            table[j] *= factor[f]

    children = [[] for _ in range(n)]
    maps = [None] * n
    for child, parent in enumerate(parents):
        if parent >= 0:
            children[parent].append(child)
            maps[child] = projection(bags[parent], bags[child][1:])
    upward = [None] * n
    for i in range(n):
        table = local[i].copy()
        for child in children[i]:
            message, mapping = upward[child], maps[child]
            for j, k in enumerate(mapping):
                table[j] *= message[k]
        upward[i] = [table[j] + table[j + 1] + table[j + 2]
                     for j in range(0, len(table), 3)]
    if any(upward[i][0] == 0 for i in range(n) if parents[i] < 0):
        return None

    downward = [None] * n
    marginals = {}
    for i in range(n - 1, -1, -1):
        if parents[i] < 0:
            downward[i] = [1]
        incoming = downward[i]
        cs = children[i]
        child_info = [(upward[c], maps[c]) for c in cs]
        child_down = [[0] * len(upward[c]) for c in cs]
        nums = [0, 0, 0]
        for j, value in enumerate(local[i]):
            product = value * incoming[j // 3]
            if not product:
                continue
            vals = []
            zeros = 0
            zero_child = -1
            for k, (message, mapping) in enumerate(child_info):
                v = message[mapping[j]]
                vals.append(v)
                if v:
                    product *= v
                else:
                    zeros += 1
                    zero_child = k
            # Exact leave-one-out products, explicitly accounting for zeros.
            if zeros == 0:
                nums[j % 3] += product
                for k, v in enumerate(vals):
                    child_down[k][child_info[k][1][j]] += product // v
            elif zeros == 1:
                child_down[zero_child][child_info[zero_child][1][j]] += product
        for child, message in zip(cs, child_down):
            downward[child] = message
        marginals[ordered[i]] = reduced_vector(nums, sum(nums))
    return marginals


UNIFORM = (1, 1, 1, 3)


def other_probabilities(data):
    priors, declared = {}, {}
    for record in data['priors']:
        a, b = record['link']
        weights = record['weights']
        if a > b:
            weights = weights[::-1]
        priors[canonical(a, b)] = reduced_vector(weights, sum(weights))
    for record in data['declared']:
        a, b = record['link']
        t = ('c2p', 'p2p', 'p2c').index(record['rel'])
        if a > b:
            t = 2 - t
        declared[canonical(a, b)] = tuple(int(j == t) for j in range(3)) + (1,)
    return priors, declared


def float_vector(vector):
    a, b, c, d = vector
    return [a / d, b / d, c / d]


def score_queries(records, ixps, priors, declared, marginals):
    results = []
    # Cache both the integer ratios (for exact comparisons) and the floating
    # vectors (used only for the full-path diagnostic, not for decisions).
    lookup = {}
    for record in records:
        path = clean(record['path'], ixps)
        result = dict(id=record['id'], path=path, status='ok', score=None,
                      full=None, witness=None, leaked=None)
        if len(set(path)) != len(path):
            result['status'] = 'loop'
        elif len(path) <= 2:
            result.update(score=1.0, full=1.0, witness=None, leaked=False)
        else:
            probabilities = []
            up, peer, down = 1.0, 0.0, 0.0
            for a, b in zip(path, path[1:]):
                directed = (a, b)
                item = lookup.get(directed)
                if item is None:
                    edge = canonical(a, b)
                    vector = declared.get(edge)
                    if vector is None:
                        vector = marginals.get(edge)
                    if vector is None:
                        vector = priors.get(edge, UNIFORM)
                    if a > b:
                        vector = (vector[2], vector[1], vector[0], vector[3])
                    item = (vector, float_vector(vector))
                    lookup[directed] = item
                vector, (u, h, d) = item
                probabilities.append(vector)
                up, peer, down = up * u, up * h, (up + peer + down) * d
            best_n, best_d, witness = 1, 1, 0
            for i, (left, right) in enumerate(zip(probabilities, probabilities[1:])):
                u, du = left[0], left[3]
                d, dd = right[2], right[3]
                num = u * dd + d * du - u * d
                den = du * dd
                if num * best_d < best_n * den:
                    best_n, best_d, witness = num, den, i
            ta, tb = record['threshold']
            result.update(score=best_n / best_d, full=up + peer + down,
                          witness=witness, leaked=(best_n * tb < ta * best_d))
        results.append(result)
    return results


def solve(data):
    validate(data)
    ixps = set(data['ixps'])
    paths, rounds = topology(data, ixps)
    structure = core_structure(paths, rounds, data['order'])
    marginals = infer(*structure)
    if marginals is None:
        return {'error': 'zero-partition'}
    priors, declared = other_probabilities(data)
    links = []
    for edge, r in sorted(rounds.items()):
        vector = marginals[edge] if r == 0 else priors.get(edge, UNIFORM)
        links.append(dict(link=edge, round=r, prob=float_vector(vector)))
    return dict(version=1, links=links,
                queries=score_queries(data['queries'], ixps, priors, declared, marginals))


def main():
    try:
        raw = sys.stdin.buffer.read(4194305)
        require(len(raw) <= 4194304)
        data = json.loads(raw.decode('utf-8'), object_pairs_hook=unique_object,
                          parse_int=parse_integer, parse_float=bad_number,
                          parse_constant=bad_number)
        answer = solve(data)
    except (Invalid, ValueError, TypeError, RecursionError, OverflowError):
        answer = {'error': 'invalid'}
    sys.stdout.write(json.dumps(answer, allow_nan=False, separators=(',', ':')) + '\n')


if __name__ == '__main__':
    main()
